class CounterViewModel:
    def __init__(self):
        self.state = 0
        self.listeners = []

    def observe(self, listener):
        self.listeners.append(listener)
        listener(self.state)

    def increment(self):
        self.state += 1
        for listener in self.listeners:
            listener(self.state)

    def reset(self):
        self.state = 0
        for listener in self.listeners:
            listener(self.state)


vm = CounterViewModel()
vm.observe(lambda s: print("экран A:", s))
vm.increment()
vm.observe(lambda s: print("экран B:", s))
vm.increment()
vm.reset()
